SELECT a.*, l.label_name AS articleLabelName
FROM bbs_article a
LEFT JOIN bbs_article_label l ON a.article_label_id = l.label_id
WHERE a.is_delete = 0

    AND a.enable = #{enable}


    AND (a.article_title LIKE concat('%', #{keywords}, '%')
         OR a.article_author LIKE concat('%', #{keywords}, '%'))


    AND a.article_label_id = #{labelId}


    AND a.create_time >= #{startTime}


    AND a.create_time <= #{endTime}

ORDER BY a.create_time DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(1)
FROM bbs_article a
WHERE a.is_delete = 0

    AND a.enable = #{enable}


    AND (a.article_title LIKE concat('%', #{keywords}, '%')
         OR a.article_author LIKE concat('%', #{keywords}, '%'))


    AND a.article_label_id = #{labelId}


    AND a.create_time >= #{startTime}


    AND a.create_time <= #{endTime}

SELECT a.*, l.label_name AS articleLabelName
FROM bbs_article a
LEFT JOIN bbs_article_label l ON a.article_label_id = l.label_id
WHERE a.is_delete = 0
  AND a.is_featured = 1

    AND (a.article_title LIKE concat('%', #{keywords}, '%')
         OR a.article_author LIKE concat('%', #{keywords}, '%'))


    AND a.article_label_id = #{labelId}


    AND a.create_time >= #{startTime}


    AND a.create_time <= #{endTime}

ORDER BY a.create_time DESC
LIMIT #{size} OFFSET #{offset}

SELECT a.*, l.label_name AS articleLabelName FROM bbs_article a LEFT JOIN bbs_article_label l ON a.article_label_id = l.label_id WHERE a.is_delete = 0 AND a.enable = 1 AND a.is_featured = 1
AND a.article_label_id = #{labelId}
ORDER BY a.create_time DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(1)
FROM bbs_article a
WHERE a.is_delete = 0
  AND a.is_featured = 1

    AND (a.article_title LIKE concat('%', #{keywords}, '%')
         OR a.article_author LIKE concat('%', #{keywords}, '%'))


    AND a.article_label_id = #{labelId}


    AND a.create_time >= #{startTime}


    AND a.create_time <= #{endTime}
